<div class="platform-card p-3 mb-4"><h2 class="h5 mb-1">Délivrabilité sur les 7 derniers jours</h2><p class="text-secondary small">Suivi des destinataires configurés pour les ventes et inventaires.</p><div class="table-responsive"><table class="table table-dark align-middle mb-0"><thead><tr><th>Canal</th><th>En attente</th><th>En traitement</th><th>Envoyés</th><th>Échoués</th><th>Total</th></tr></thead><tbody>@forelse($deliveryStats->groupBy('channel') as $channel=>$rows)@php($counts=$rows->pluck('total','status'))<tr><td class="text-uppercase fw-semibold">{{ strtoupper($channel) }}</td><td>{{ $counts['pending']??0 }}</td><td>{{ $counts['processing']??0 }}</td><td class="text-success">{{ $counts['sent']??0 }}</td><td class="text-danger">{{ $counts['failed']??0 }}</td><td>{{ $rows->sum('total') }}</td></tr>@empty<tr><td colspan="6" class="text-center text-secondary py-4">Aucune livraison enregistrée sur cette période.</td></tr>@endforelse</tbody></table></div></div>

<div class="platform-card p-3"><div class="d-flex justify-content-between"><div><h2 class="h5 mb-1">Jobs échoués récents</h2><p class="small text-secondary">La relance remet le job dans la file ; elle ne garantit pas sa réussite.</p></div></div><div class="table-responsive"><table class="table table-dark table-hover align-middle"><thead><tr><th>Date</th><th>File</th><th>Connexion</th><th>Identifiant</th><th></th></tr></thead><tbody>@forelse($failedJobs as $job)<tr><td>{{ \Carbon\Carbon::parse($job->failed_at)->format('d/m/Y H:i:s') }}</td><td>{{ $job->queue }}</td><td>{{ $job->connection }}</td><td><small>{{ $job->uuid }}</small></td><td><button class="btn btn-sm btn-outline-warning retry-job" data-url="{{ route('platform.health.jobs.retry',$job->uuid) }}"><i class="bi bi-arrow-repeat me-1"></i>Relancer</button></td></tr>@empty<tr><td colspan="5" class="text-center text-secondary py-5">Aucun job échoué.</td></tr>@endforelse</tbody></table></div></div>
