@push('scripts')<script>document.querySelectorAll('.retry-job').forEach(button=>button.addEventListener('click',()=>Swal.fire({title:'Relancer ce job ?',text:'Vérifiez d’abord que la cause de l’échec est corrigée.',icon:'warning',input:'textarea',inputLabel:'Motif obligatoire',showCancelButton:true,confirmButtonText:'Oui, relancer',cancelButtonText:'Annuler',showLoaderOnConfirm:true,allowOutsideClick:()=>!Swal.isLoading(),preConfirm:async reason=>{if(!reason||reason.trim().length<5)return Swal.showValidationMessage('Indiquez un motif d’au moins 5 caractères.');const r=await fetch(button.dataset.url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({reason:reason.trim()})});const d=await r.json().catch(()=>({}));if(!r.ok)return Swal.showValidationMessage(d.message||'Relance impossible.');return d}}).then(result=>{if(result.isConfirmed)Swal.fire({icon:'success',title:'Job relancé',text:result.value.message}).then(()=>location.reload())})));</script>@endpush
